let bookSection='home',bookMonth=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date()).slice(0,7);
const bookNames=['TAI SIAM Tachileik','TAI SIAM 2','MOK SIO','TAI SIAM Murng Pan'];
const bookCategories=[['sales','ขายน้ำมันรายวัน','มิเตอร์ ลิตรขาย ราคา ส่วนลด และขายเชื่อ'],['monthly','ยอดขายและค่าใช้จ่ายรายเดือน','ยอดขายแยกประเภทน้ำมัน พร้อมค่าใช้จ่าย'],['expenses','ค่าใช้จ่ายรายวัน','ค่าแรง ค่าน้ำไฟ ค่าซ่อม และค่าใช้จ่ายอื่น'],['purchases','ซื้อน้ำมันเข้า','ผู้ขาย ลิตรซื้อ ราคาซื้อ และยอดจ่าย'],['cash','เงินรับ–เงินจ่ายรายเดือน','ติดตามเงินรับและเงินจ่ายจริงของสาขา']];
function bookSelect(){let names=[...new Set([...bookNames,...(xlState?.records||[]).map(r=>r.branch)])];return `<label>เลือกสาขา <select aria-label="สาขางานบัญชี" onchange="xlBranch=this.value;render()">${names.map(n=>`<option ${n===xlBranch?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`}
function bookGo(section){bookSection=section;xlView='ledger';go('reports')}
const bookLayout=xlLayout;xlLayout=function(title,sub,body){return bookLayout(title,sub,`<div class="book-toolbar"><button onclick="bookGo('home')">← งานบัญชี 5 หมวด</button>${bookSelect()}</div>`+body)};
const bookSalesPage=reportsPage;
reportsPage=function(){
 if(!canAccount()||!xlLoaded)return bookSalesPage();
 if(!xlState)return head('งานบัญชียังไม่พร้อมใช้งาน','หน้านี้ต้องเชื่อมต่อระบบบันทึกบัญชี')+`<div class="note error">${esc(xlError||'ไม่พบระบบบัญชี')}</div><section class="panel"><p>กรุณาลองเชื่อมต่อใหม่ หากยังไม่สำเร็จ ให้ผู้ดูแลตรวจการตั้งค่าระบบบัญชี</p><button onclick="xlLoad()">ลองเชื่อมต่อใหม่</button><button onclick="go('tasks')">กลับหน้าต้นแบบ</button></section>`;
 if(xlView==='files')return bookSalesPage();
 if(bookSection==='sales')return bookSalesPage();
 if(bookSection==='home')return xlLayout('งานบัญชีสาขา','เลือกสาขา แล้วเลือกหมวดที่ต้องการทำงาน',`<div class="book-grid">${bookCategories.map(([id,title,sub],i)=>`<button class="panel book-card" onclick="bookGo('${id}')"><span class="eyebrow">0${i+1}</span><h2>${title}</h2><p>${sub}</p><span>เปิดหมวด →</span></button>`).join('')}</div><section class="panel"><h2>Excel รวมเล่ม</h2><p>รวม 5 หมวด พร้อมภาพรวมและข้อมูลต้นทางในไฟล์เดียว หมวดค่าใช้จ่าย/ซื้อ/เงินสดเป็นโครงร่างรอเทียบแบบฟอร์มจริง</p><button class="primary" onclick="xlFrom='';xlTo='';xlExport()">ส่งออกทุกหมวดของสาขานี้</button><p class="muted">นำกลับเข้าเว็บได้เฉพาะชีต “รายการเว็บ” (ยอดขายรายวัน) ค่าใช้จ่าย/ซื้อบันทึกผ่านเว็บได้ ส่วนหมวดอื่นใช้เป็นแบบร่างใน Excel ก่อน</p></section>`);
 if(['expenses','purchases'].includes(bookSection))return bookEntriesPage(bookSection);
 return bookMonthlyPage(bookSection);
};
function bookRows(kind){return (xlState?.[kind]||[]).filter(r=>r.branch===xlBranch&&r.date.startsWith(bookMonth))}
function bookPeriod(){return `<label>เดือน <input aria-label="เดือนบัญชี" type="month" value="${bookMonth}" onchange="bookMonth=this.value;render()"></label>`}
function bookEntriesPage(kind){let rows=bookRows(kind),title=kind==='expenses'?'ค่าใช้จ่ายรายวัน':'ซื้อน้ำมันเข้า';return xlLayout(title,'แบบร่างช่องข้อมูล — รอเทียบไฟล์ Excel หมวดนี้',`<div class="book-toolbar">${bookPeriod()}<button class="primary" onclick="bookEntryForm('${kind}')">+ บันทึก${title}</button></div><div class="note">${kind==='expenses'?'ไม่รวมซื้อน้ำมัน เพื่อไม่ให้ยอดซ้ำกับหมวดซื้อน้ำมันเข้า':'ยอดรับเข้าจาก Excel เดิมยังไม่ถือเป็นรายการซื้อที่ยืนยันแล้ว และไม่มีข้อมูลว่าจ่ายเงินแล้วเท่าไร'} · ยอดจ่ายในฟอร์มหมายถึงจ่ายในวันที่รายการเท่านั้น</div><section class="panel">${table(['วันที่','รายละเอียด','ปริมาณ / ราคา','ยอดรายการ','จ่ายจริงวันนั้น','เอกสาร'],rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.description)}</td><td>${kind==='purchases'?esc(xlFuelLabel(r.fuel))+' · '+fmt(r.liters)+' ลิตร × '+fmt(r.price):'—'}</td><td>${fmt(r.amount)}</td><td>${r.paid===null?'ยังไม่ระบุ':fmt(r.paid)}</td><td>${esc(r.reference)}</td></tr>`))}</section>`)}
function bookEntryForm(kind){modal(kind==='expenses'?'บันทึกค่าใช้จ่าย':'บันทึกซื้อน้ำมัน',`<form onsubmit="event.preventDefault();bookSave(this,'${kind}')"><p>${esc(xlBranch)} · แบบร่างหมวดบัญชี</p>${field('วันที่รายการ','entryDate',new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date()),'date','required')}${field(kind==='expenses'?'รายละเอียดค่าใช้จ่าย':'ผู้ขาย / รายละเอียด','description','','text','required')}${kind==='purchases'?`<label>ชนิดน้ำมัน<select name="fuel"><option value="ดีเซล">ดีเซล</option><option value="95">น้ำมัน 95</option><option value="91">น้ำมัน 91</option></select></label>${field('ลิตรซื้อ','liters','','number','min="0" step="0.001" required')}${field('ราคาซื้อ / ลิตร','price','','number','min="0" step="0.001" required')}`:field('ยอดค่าใช้จ่าย (บาท)','amount','','number','min="0" step="0.01" required')}${field('เงินที่จ่ายในวันที่รายการ (เว้นว่างถ้ายังไม่ทราบ)','paid','','number','min="0" step="0.01"')}${field('เลขที่เอกสาร / หมายเหตุ','reference')}<p>0 = ยืนยันว่ายังไม่จ่าย · เว้นว่าง = ยังไม่ทราบ · การจ่ายคนละวันยังไม่รองรับในแบบร่างนี้</p><div id="bookError" role="alert"></div><button class="primary">บันทึก</button></form>`)}
async function bookSave(form,kind){let x={kind,branch:xlBranch,revision:xlState.revision,date:form.entryDate.value,description:form.description.value,reference:form.reference.value,paid:form.paid.value===''?null:Number(form.paid.value)};if(kind==='purchases')Object.assign(x,{fuel:form.fuel.value,liters:Number(form.liters.value),price:Number(form.price.value)});else x.amount=Number(form.amount.value);let button=form.querySelector('button.primary');button.disabled=true;try{await xlApi('/book-entry',x);bookMonth=x.date.slice(0,7);closeModal();await xlLoad();toast('บันทึกแล้ว')}catch(e){$('#bookError').textContent=e.message}finally{button.disabled=false}}
function bookMonthlyPage(kind){let sales=(xlState?.records||[]).filter(r=>r.branch===xlBranch&&r.date.startsWith(bookMonth)),expenses=bookRows('expenses'),purchases=bookRows('purchases'),sum=(xs,key)=>xs.reduce((s,r)=>s+(r[key]||0),0);let rows=['ดีเซล','95','91'].map(f=>{let ls=sales.flatMap(r=>r.lines).filter(l=>l.fuel===f);return `<tr><td>${xlFuelLabel(f)}</td><td>${fmt(sum(ls,'liters'))}</td><td>${fmt(ls.reduce((s,l)=>s+l.liters*l.price,0))}</td></tr>`});return xlLayout(kind==='monthly'?'ยอดขายและค่าใช้จ่ายรายเดือน':'เงินรับ–เงินจ่ายรายเดือน','รวมเฉพาะรายการที่บันทึกในสาขาและเดือนที่เลือก',`<div class="book-toolbar">${bookPeriod()}<button onclick="bookExportMonth()">ส่งออก Excel รวมเดือนนี้</button></div>${kind==='monthly'?`<section class="panel">${table(['น้ำมัน','ลิตรขาย','ยอดขายก่อนปรับ (บาท)'],rows)}<p>ค่าใช้จ่ายที่บันทึก: ${fmt(sum(expenses,'amount'))} บาท (${expenses.length} รายการ)</p><p>ซื้อน้ำมันที่บันทึก: ${fmt(sum(purchases,'amount'))} บาท (${purchases.length} รายการ) · แสดงแยก ไม่ใช่ต้นทุนขาย</p></section><div class="note">${sales.length} วันขาย · 0 รายการหมายถึงยังไม่มีข้อมูล ไม่ยืนยันว่าทั้งเดือนไม่มีค่าใช้จ่าย · ยังไม่แสดงกำไรสุทธิ</div>`:`<section class="panel"><h2>ข้อมูลเงินสดยังไม่ครบ</h2><p>เงินรับขายและรายรับอื่น: รอรายการรับเงินจริง</p><p>จ่ายค่าใช้จ่ายที่ระบุแล้ว: ${fmt(sum(expenses,'paid'))} บาท</p><p>จ่ายซื้อน้ำมันที่ระบุแล้ว: ${fmt(sum(purchases,'paid'))} บาท</p><p>รายการที่ยังไม่ระบุยอดจ่าย: ${[...expenses,...purchases].filter(r=>r.paid===null).length}</p><div class="note">ไม่ใช้ยอดขายแทนยอดเงินรับ และยังไม่คำนวณยอดสุทธิ/เงินคงเหลือ ชีตเงินรับ–เงินจ่ายใน Excel มีช่องเติมรายรับจริงและช่องยืนยันความครบถ้วนให้ทดลองก่อน</div></section>`}`)}
function bookExportMonth(){if(!bookMonth)return toast('เลือกเดือน');xlFrom=bookMonth+'-01';let [y,m]=bookMonth.split('-').map(Number);xlTo=bookMonth+'-'+new Date(y,m,0).getDate();xlExport()}
const bookNav=simpleNav;simpleNav=function(){return bookNav().replace('Excel · งานบัญชี','งานบัญชี · 5 หมวด')};
const bookManualSaved=xlSaveManual;xlSaveManual=async function(form){bookSection='sales';return bookManualSaved(form)};
render();
